    reg bps_sel, sign_sel;
    reg [12:0] cnt;
    reg [4:0] tran_cnt;

    wire recv_comp;
    assign recv_comp = (tran_cnt == 17 && bps_sel);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: state <= ~rs_rx ? TRAN : IDLE;
                TRAN: state <= recv_comp ? IDLE : TRAN;
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bps_sel <= 1'b0;
            sign_sel <= 1'b0;
            cnt <= 'h0;
            tran_cnt <= 'h0;
