                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    3'h2: if (cnt == bps38400_2) begin
                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    3'h3: if (cnt == bps57600_2) begin
                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    3'h4: if (cnt == bps115200_2) begin
                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    3'h5: if (cnt == bps256000_2) begin
                            cnt <= 'h0;
                            bps_sel <= ~sign_sel;
                            sign_sel <= ~sign_sel;
                            tran_cnt <= tran_cnt + 1'b1;
                          end else begin
                            cnt <= cnt + 1'b1;
                            bps_sel <= 1'b0;
                          end
                    default: begin
                                cnt <= 'h0;
                                tran_cnt <= 0;
                                bps_sel <= 'h0;
                                sign_sel <= 'h0;
                             end
                endcase
            end else begin
                cnt <= 'h0;
                sign_sel <= 'h0;
                bps_sel <= 1'b0;
                tran_cnt <= 'h0;
                bps_sel <= 1'b0;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_in <= 'h0;
            data_sign <= 'h0;
        end else begin
            if (bps_sel) begin
                if (tran_cnt > 2 && tran_cnt <= 16) begin
                    data_in[tran_cnt[4:1] - 1] <= rs_rx;
                end
                data_sign <= (tran_cnt == 17) ? 1'b1 : 1'b0;
            end else begin
                data_sign <= 1'b0;
            end
        end
    end

