        2'b01: begin
          Q <= shift_reg[2:0];
          state <= 2'b11;
        end
        2'b11: begin
          Q <= shift_reg[1:0] ^ shift_reg[3];
          state <= 2'b10;
        end
        2'b10: begin
          Q <= shift_reg[0] ^ shift_reg[2];
          state <= 2'b01;
        end
      endcase
    end
  end

