module top_module (
    input clk,
    input rst,
    input [3:0] in,
    input load,
    output reg [15:0] data_out,
    output reg [3:0] count
);

wire [15:0] decoder_out;
reg [15:0] shift_reg;

// 4-to-16 decoder module
decoder_4to16 decoder (
    .in(in),
    .out(decoder_out)
);

// 16-bit shift register module
shift_register_16bit shift_reg_inst (
    .clk(clk),
    .rst(rst),
    .load(load),
    .data_in(decoder_out),
    .data_out(shift_reg)
);

