    input b,
    output y
);

assign y = a & b;

endmodule

// 2-input OR gate
module or_gate (
    input a,
    input b,
    output y
);

assign y = a | b;

endmodule

// 2-input XOR gate
module xor_gate (
    input a,
    input b,
    output y
);

assign y = a ^ b;

endmodule

