reg [3:0] shifted_data;

twos_complement tc_inst (
    .num(num),
    .twos_comp(twos_comp)
);

barrel_shifter bs_inst (
    .DATA(DATA),
    .SHIFT(SHIFT),
    .RESET(RESET),
    .OUT(shifted_data)
);

always @ (posedge clk or posedge RESET) begin
    if (RESET) begin
