    .zn(C1),
    .a(S4[3]),
    .b(S3[3]),
    .c(Cin)
  );

  // Final sum calculation
  nand3 #(4) S5[3:0] (
    .zn(S),
    .a(S4[3:0]),
    .b(C3),
    .c(C2)
  );

  nand3 #(4) S6[3:0] (
