module shift_register (
  input clk,
  input reset,
  input [7:0] data_in,
  input shift_direction,
  input load,
  output [7:0] q
);

  reg [7:0] shift_reg;

  always @(negedge clk or posedge reset) begin
    if (reset) begin
      shift_reg <= 8'h34;
    end else begin
      if (load) begin
        shift_reg <= data_in;
      end else begin
        if (shift_direction) begin
          shift_reg <= {shift_reg[6:0], shift_reg[7]};
        end else begin
          shift_reg <= {shift_reg[0], shift_reg[7:1]};
        end
      end
    end
  end

  assign q = shift_reg;

endmodule


