    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] sum_wire;
    wire c1, c2, c3;

    assign sum = sum_wire;
    assign cout = c3;

    // full adder for least significant bit
    full_adder fa0(
        .a(a[0]),
