module PLL (
  input ref_clk,
  input reset,
  input enable,
  output locked_clk
);

parameter N = 2; // multiplication factor
parameter M = 1; // division factor

// Phase detector
reg pd_out;
always @(posedge ref_clk or posedge locked_clk) begin
  pd_out <= ref_clk ^ locked_clk;
end

// Charge pump
reg [1:0] cp_out;
always @(posedge pd_out) begin
  if (pd_out) begin
    cp_out <= cp_out + 2'b01;
  end else begin
    cp_out <= cp_out - 2'b01;
  end
end

// Loop filter
reg [7:0] lf_out;
always @(posedge ref_clk) begin
  lf_out <= lf_out + cp_out;
end

