           BEQ   = 6'b000100,
           RTYPE = 6'b000000,
           J     = 6'b000010,
           JAL   = 6'b000011,
           ADDI  = 6'b001000,
           ANDI  = 6'b001100,
           ORI   = 6'b001101,
           XORI  = 6'b001110,
           SLTI  = 6'b001010;

