        ex_alu_src_b = 1'b1;
        ex_dst_reg_sel = 2'b00;
        ex_alu_op = 2'b00;
        wb_mem_to_reg = 1'b1;
        mem_read = 1'b1;
        wb_reg_write = 1'b1;
