        ex_dst_reg_sel = 2'b01;
        ex_alu_op = special[2:0];
        wb_reg_write = 1'b1;
    end
end

// Immediate operations
always @* begin
    if (opcode == ADDI || opcode == ANDI || opcode == ORI || opcode == XORI || opcode == SLTI) begin
        ex_imm_command = 1'b1;
        ex_alu_src_b = 1'b1;
        ex_dst_reg_sel = 2'b00;
        ex_alu_op = special[2:0];
        wb_reg_write = 1'b1;
    end
end

// Branch operations
always @* begin
    if (opcode == BEQ) begin
        if (branch_eq) begin
            if_pc_source = 2'b01;
