        .cout(),
        .overflow(adder_overflow)
    );

    // Shift register module
    wire [3:0] shift_out;
    shift_register shift_inst (
        .clk(clk),
        .reset(reset),
        .data(data),
        .enable(1'b1),
        .load(1'b0),
        .shift_left(select),
        .q(shift_out)
    );

