module carry_select_adder (
    input [7:0] a,
    input [7:0] b,
    input cin,
    output [8:0] s,
    output cout,
    output overflow
);

    wire [7:0] p = a + b;
    wire [7:0] g = a & b;
    wire [7:0] u = p + (g << 1);
    wire [7:0] v = p - (g << 1);

    assign s = (cin == 1'b0) ? u : v;
    assign cout = (g[6] | (g[5] & cin));
    assign overflow = (a[7] == b[7] && s[7] != a[7]);

endmodule

